svg.script:
(async()=>{
 const root="/gh/unblockedgames99x-code/gsn-console-cdn@v20260927-31/",status=document.getElementById('status');
 try {
  const registration=await navigator.serviceWorker.register(root+'launcher-sw.js',{scope:root});
  const worker=registration.installing||registration.waiting||registration.active;
  if(worker.state!=='activated')await new Promise((resolve,reject)=>{const timer=setTimeout(()=>reject(Error('Connection timed out. Please refresh.')),30000);worker.addEventListener('statechange',()=>{if(worker.state==='activated'){clearTimeout(timer);resolve()}else if(worker.state==='redundant'){clearTimeout(timer);reject(Error('Please refresh to start the console.'))}})});
  const frame=document.createElementNS('http://www.w3.org/1999/xhtml','iframe');
  frame.title='<GSN> console';frame.setAttribute('allow','autoplay; fullscreen; gamepad; encrypted-media; picture-in-picture; clipboard-write; microphone; camera');frame.setAttribute('allowfullscreen','true');
  frame.style.cssText='position:fixed;inset:0;width:100%;height:100%;border:0;background:#080b14';
  frame.addEventListener('load',()=>status.remove(),{once:true});frame.src=root+'index.html';document.getElementById('host').appendChild(frame);
 }catch(error){status.textContent='Could not start <GSN>. '+error.message;}
})();
